{"function":"() => {
const parse=c=>{const m=c.match(/[\d.]+/g);return m?m.map(Number):[0,0,0,0];};
const lum=([r,g,b])=>{const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b)};
const bgOf=e=>{while(e){const c=getComputedStyle(e).backgroundColor;const p=parse(c);if(p.length<4?true:p[3]>0){if(c!=='rgba(0, 0, 0, 0)')return p;}e=e.parentElement||e.getRootNode().host;}return [255,255,255];};
const res=[];const seen=new Set();
const all=[];
const collect=root=>{root.querySelectorAll('*').forEach(e=>{all.push(e);if(e.shadowRoot)collect(e.shadowRoot);});};
collect(document);
for(const e of all){
  const txt=[...e.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent.trim()).join(' ').trim();
  if(!txt) continue;
  if(e.closest && e.closest('style,script')) continue;
  const cs=getComputedStyle(e); if(cs.visibility==='hidden'||cs.display==='none') continue;
  const r=e.getBoundingClientRect(); if(r.width===0) continue;
  const fg=parse(cs.color); const bg=bgOf(e);
  const L1=lum(fg),L2=lum(bg); const cr=(Math.max(L1,L2)+0.05)/(Math.min(L1,L2)+0.05);
  const fs=parseFloat(cs.fontSize), fw=parseInt(cs.fontWeight);
  const large= fs>=24 || (fs>=18.66&&fw>=700);
  const key=txt.slice(0,30)+cs.color+bg;
  if(cr<(large?3:4.5) && !seen.has(key)){seen.add(key);res.push({t:txt.slice(0,40),tag:e.tagName,cls:(typeof e.className==='string'?e.className:'').slice(0,50),fg:cs.color,bg:bg.join(','),cr:cr.toFixed(2),fs,fw,disabled:!!(e.closest&&e.closest('[disabled]'))});}
}
return res;
}"}

